import{_ as t,c as a,o as s,al as i}from"./chunks/framework.CT7RwC5a.js";const h=JSON.parse('{"title":"Custom MAVLink Messages","description":"","frontmatter":{},"headers":[],"relativePath":"zh/mavlink/custom_messages.md","filePath":"zh/mavlink/custom_messages.md"}'),o={name:"zh/mavlink/custom_messages.md"};function n(d,e,r,l,m,c){return s(),a("div",null,e[0]||(e[0]=[i('<h1 id="custom-mavlink-messages" tabindex="-1">Custom MAVLink Messages <a class="header-anchor" href="#custom-mavlink-messages" aria-label="Permalink to &quot;Custom MAVLink Messages&quot;">​</a></h1><p>A custom <a href="./../middleware/mavlink.html">MAVLink message</a> is one that isn&#39;t in the standard MAVLink definitions that are included into PX4 by default.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you use a custom definition you will fork and maintain PX4, your ground station, and any other SDKs that communicate with it. Generally you should use (or add to) the standard definitions if at all possible to reduce the maintenance burden.</p></div><h2 id="adding-custom-xml" tabindex="-1">Adding Custom XML <a class="header-anchor" href="#adding-custom-xml" aria-label="Permalink to &quot;Adding Custom XML&quot;">​</a></h2><p>Custom definitions can be added in a new dialect file in the same directory as <a href="./../mavlink/adding_messages.html">when using the standard XML definitions</a>. For example, create <code>PX4-Autopilot/src/modules/mavlink/mavlink/message_definitions/v1.0/custom_messages.xml</code>, and set <code>CONFIG_MAVLINK_DIALECT</code> to build the new file for SITL. This dialect file should include <code>development.xml</code> so that all the standard definitions are also included.</p><p>For initial prototyping, or if you intend your message to be &quot;standard&quot;, you can also add your messages to <code>common.xml</code> (or <code>development.xml</code>). This simplifies building, because you don&#39;t need to modify the dialect that is built.</p><p>The MAVLink developer guide explains how to define new messages in <a href="https://mavlink.io/en/guide/define_xml_element.html" target="_blank" rel="noreferrer">How to Define MAVLink Messages &amp; Enums</a>.</p><p>You can check that your new messages are built by inspecting the headers generated in the build directory (<code>/build/&lt;build target&gt;/mavlink/</code>). If your messages are not built they may be incorrectly formatted, or use clashing ids. Inspect the build log for information.</p><p>Once the message is being built you can stream, receive, or otherwise use it, as described in the following sections.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <a href="https://mavlink.io/en/getting_started/" target="_blank" rel="noreferrer">MAVLink Developer guide</a> has more information about using the MAVLink toolchain.</p></div><h2 id="另一种自定义mavlink消息的办法" tabindex="-1">另一种自定义MAVlink消息的办法 <a class="header-anchor" href="#另一种自定义mavlink消息的办法" aria-label="Permalink to &quot;另一种自定义MAVlink消息的办法&quot;">​</a></h2><p>Sometimes there is the need for a custom MAVLink message with content that is not fully defined.</p><p>For example when using MAVLink to interface PX4 with an embedded device, the messages that are exchanged between the autopilot and the device may go through several iterations before they are stabilized. In this case, it can be time-consuming and error-prone to regenerate the MAVLink headers, and make sure both devices use the same version of the protocol.</p><p>An alternative - and temporary - solution is to re-purpose debug messages. Instead of creating a custom MAVLink message <code>CA_TRAJECTORY</code>, you can send a message <code>DEBUG_VECT</code> with the string key <code>CA_TRAJ</code> and data in the <code>x</code>, <code>y</code> and <code>z</code> fields. See <a href="./../debug/debug_values.html">this tutorial</a> for an example usage of debug messages.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This solution is not efficient as it sends character string over the network and involves comparison of strings. It should be used for development only!</p></div><h2 id="testing-updating-ground-stations" tabindex="-1">Testing &amp; Updating Ground Stations <a class="header-anchor" href="#testing-updating-ground-stations" aria-label="Permalink to &quot;Testing &amp; Updating Ground Stations&quot;">​</a></h2><p>Testing the code and updating ground stations is done in the same way as when <a href="./../mavlink/adding_messages.html">Adding New Standard MAVLink Definitions </a>.</p>',17)]))}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
